4px; }\n  .rdoc .section-title { font-size: 8.5pt; font-weight: 700; color: #000b59; text-transform: uppercase; letter-spacing: 0.6px; padding-bottom: 4px; border-bottom: 1px solid #e2e8f0; margin-bottom: 8px; }\n  .rdoc .section-title::before { content: \'\'; display: inline-block; width: 4px; height: 12px; background: #f55400; border-radius: 2px; margin-right: 6px; vertical-align: -1px; }\n\n  .rdoc .data-grid { width: 100%; border-collapse: separate; border-spacing: 0; border: 1px solid #e2e8f0; border-radius: 6px; overflow: hidden; font-size: 9pt; }\n  .rdoc .data-grid td { padding: 7px 12px; border-bottom: 1px solid #f1f5f9; vertical-align: middle; }\n  .rdoc .data-grid tr:last-child td { border-bottom: none; }\n  .rdoc .data-grid tr:nth-child(even) td { background: #fafafa; }\n  .rdoc .data-label { width: 28%; font-weight: 700; color: #64748b; border-right: 1px solid #f1f5f9; }\n  .rdoc .data-val { font-weight: 600; color: #0f172a; }\n\n  .rdoc .letter-body p { font-size: 9.4pt; }\n  .rdoc .letter-body strong { color: #000b59; }\n\n  .rdoc .note-box { background: #f8fafc; border: 1px solid #e2e8f0; border-left: 3.5px solid #000b59; border-radius: 6px; padding: 9px 12px; margin: 4px 0 14px 0; }\n  .rdoc .note-box p { margin: 0; font-size: 9pt; color: #334155; }\n  .rdoc .note-box strong { color: #000b59; }\n\n  .rdoc .sig-single { width: 55%; margin: 10px auto 0 auto; text-align: center; page-break-inside: avoid; }\n  .rdoc .sig-role { font-size: 7.5pt; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; text-align: left; margin-bottom: 4px; }\n  .rdoc .sig-img-wrap { height: 96px; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; margin-bottom: 4px; }\n  .rdoc .sig-img-wrap img { max-height: 84px; max-width: 230px; margin: 0 auto !important; }\n  .rdoc .sig-line { border-top: 1.5px solid #000b59; margin-bottom: 5px; }\n  .rdoc .sig-name { font-size: 9pt; font-weight: 700; color: #000b59; text-transform: uppercase; }\n  .rdoc .sig-details { font-size: 7.5pt; color: #64748b; line-height: 1.35; }\n\n  .rdoc .doc-footer { margin-top: 22px; text-align: center; }\n  .rdoc .doc-footer .line { height: 2px; background: #f55400; border-radius: 1px; margin-bottom: 7px; }\n  .rdoc .doc-footer .addr { color: #000b59; font-size: 7.5pt; line-height: 1.4; letter-spacing: 0.3px; }\n  .rdoc .doc-footer .legal { color: #94a3b8; font-size: 6.8pt; margin-top: 2px; }\n\n  .rdoc .ref-box { background: #f8fafc; border: 1px solid #e2e8f0; border-left: 3.5px solid #f55400; border-radius: 6px; padding: 7px 12px; margin: 0 0 12px 0; font-size: 9pt; }\n  .rdoc .ref-box strong { color: #000b59; text-transform: uppercase; letter-spacing: 0.3px; font-size: 8pt; }\n\n  .rdoc .metrics-card { display: table; width: 100%; table-layout: fixed; background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; overflow: hidden; margin: 4px 0 14px 0; }\n  .rdoc .metric-item { display: table-cell; padding: 10px 14px; border-right: 1px solid #e2e8f0; vertical-align: top; }\n  .rdoc .metric-item:last-child { border-right: none; }\n  .rdoc .metric-label { font-size: 7.5pt; font-weight: 700; color: #64748b; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 2px; }\n  .rdoc .metric-value { font-size: 10pt; font-weight: 700; color: #000b59; }\n  .rdoc .metric-value-primary { font-size: 10pt; font-weight: 800; color: #f55400; }\n</style>\n\n\n<div class=\"rdoc\">\n\n  <table class=\"doc-header-table\">\n    <tr>\n      <td class=\"header-logo-cell\"><img src=\"{{logo_src}}\" alt=\"LOG&amp;SER\" class=\"logo-img\"></td>\n      <td class=\"header-title-cell\">\n        <div class=\"doc-title\">Formato autorización de descuento por nómina</div>\n        <div class=\"doc-subtitle\">Gestión de Talento Humano</div>\n        <div class=\"doc-subdetail\">Descuento específico por cuotas</div>\n      </td>\n      <td class=\"header-meta-cell\">\n        <div class=\"meta-code\">{{codigo_formato}}</div>\n        <div class=\"meta-ver\">Versión {{version_formato}}</div>\n        <div class=\"meta-date\">{{fecha_formato}}</div>\n      </td>\n    </tr>\n  </table>\n\n  <div class=\"letter-meta\">\n    <p class=\"city\">{{ciudad}}, {{fecha}}</p>\n    <p>Señores:</p>\n    <p><strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong></p>\n    <p>NIT: 900.318.733-1</p>\n  </div>\n\n  <div class=\"ref-box\"><strong>Asunto:</strong> Autorización de descuento por nómina</div>\n\n  <div class=\"metrics-card\">\n    <div class=\"metric-item\">\n      <div class=\"metric-label\">Número de cuotas</div>\n      <div class=\"metric-value\">{{cuotas}}</div>\n    </div>\n    <div class=\"metric-item\">\n      <div class=\"metric-label\">Valor</div>\n      <div class=\"metric-value-primary\">{{valor}}</div>\n    </div>\n    <div class=\"metric-item\">\n      <div class=\"metric-label\">Concepto</div>\n      <div class=\"metric-value\">{{motivo}}</div>\n    </div>\n  </div>\n\n  <div class=\"letter-body\">\n    <p>Yo, <strong>{{nombre_trabajador}}</strong>, mayor de edad, identificado con documento de identidad No. <strong>{{identificacion}}</strong>, en mi calidad de trabajador con el cargo de <strong>{{cargo}}</strong> de la empresa <strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong>, autorizo expresa e irrevocablemente para que, de mi salario, bonificaciones, prestaciones sociales, o de cualquier suma de dinero que se vaya generando a mi favor, me sean descontados en <strong>{{cuotas}}</strong> cuotas, por valor de <strong>{{valor}}</strong> para el pago de <strong>{{motivo}}</strong>, aun en el evento de encontrarme disfrutando de vacaciones o licencias.</p>\n    <p>Igualmente autorizo expresa e irrevocablemente a <strong>APOYO LOGÍSTICO Y OPERATIVO SAS</strong>, a descontar de mi salario, sueldo, bonificaciones, prestaciones sociales e indemnizaciones a que tengo derecho, las cuotas que se estén adeudando si se llegare a terminar mi contrato de trabajo por cualquier causa.</p>\n  </div>\n\n  <p style=\"margin-bottom:2px\">Atentamente,</p>\n\n  <div class=\"sig-single\">\n    <div class=\"sig-role\">Autoriza</div>\n    <div class=\"sig-img-wrap\">{{firma_trabajador}}</div>\n    <div class=\"sig-line\"></div>\n    <div class=\"sig-name\">{{nombre_trabajador}}</div>\n    <div class=\"sig-details\">CC {{identificacion}} · {{cargo}}</div>\n  </div>\n\n  <div class=\"doc-footer\">\n    <div class=\"line\"></div>\n    <div class=\"addr\">DIAGONAL 74B No. 33° 51-55 — ANTIGUA TRANSVERSAL 39° No 70° 51-55 — LAURELES - MEDELLÍN</div>\n    <div class=\"legal\">Apoyo Logístico y Operativo S.A.S. &bull; Documento electrónico — Ley 527 de 1999</div>\n  </div>\n\n</div>\n'
WHERE id_plantilla = 11 AND nombre_proceso = 'descuento_especifico';

